const Rank=require("../models/rankModel"),handleErrors=require("../utilities/handle_errors")["handleErrors"],create_rank=(a,n,e)=>{Rank.create(a.body).then(e=>n.status(200).send(e)).catch(e=>n.status(422).send(handleErrors(e,a,"rank")))},get_ranks=(e,a,n)=>{Rank.find({}).lean().then(e=>a.status(200).send({ranks:e})).catch(n)},get_admin_ranks=(e,n,t)=>{const r=e.query.page-1||0;Rank.find({}).count().then(a=>{Rank.find({}).skip(30*r).limit(30).then(e=>n.status(200).send({ranks:e,total_ranks:a,per_page:30})).catch(t)})},get_single_rank=(e,a,n)=>{Rank.findById({_id:e.params.id}).then(e=>a.status(200).send(e)).catch(n)},update_rank=(e,a,n)=>{Rank.findByIdAndUpdate({_id:e.params.id},e.body,{new:!0}).then(e=>a.status(200).send(e)).catch(n)},delete_rank=(e,a,n)=>{Rank.findByIdAndDelete({_id:e.params.id},{new:!0}).then(e=>a.status(200).send(e)).catch(n)};module.exports={create_rank:create_rank,update_rank:update_rank,get_single_rank:get_single_rank,get_admin_ranks:get_admin_ranks,get_ranks:get_ranks,delete_rank:delete_rank};